#!/usr/bin/env bash\n# Verifica invariantes en una BD existente; sin conexión no afirma éxito.\nset -euo pipefail\n\nPGHOST="${PGHOST:-localhost}"\nPGPORT="${PGPORT:-5432}"\nPGUSER="${PGUSER:-postgres}"\nPGDATABASE="${PGDATABASE:-construction}"\nTENANT="${1:-}"\nPSQL=(psql -X -v ON_ERROR_STOP=1 -h "$PGHOST" -p "$PGPORT" -U "$PGUSER" -d "$PGDATABASE" -t -A)\n\nif ! command -v psql >/dev/null 2>&1; then\n  echo "BLOCKED: psql no está instalado; invariantes NO verificados."\n  exit 2\nfi\nif ! "${PSQL[@]}" -c 'SELECT 1' >/dev/null 2>&1; then\n  echo "BLOCKED: no se pudo conectar a $PGHOST:$PGPORT/$PGDATABASE como $PGUSER."\n  exit 2\nfi\nfail=0\ncheck_zero() {\n  local name="$1" query="$2" actual\n  if actual=$("${PSQL[@]}" -c "$query" 2>/dev/null); then :; else actual="ERR"; fi\n  actual="$(printf '%s' "$actual" | tr -d '[:space:]')"\n  if [[ "$actual" == "0" ]]; then echo "PASS | $name"; else echo "FAIL | $name | esperado=0 obtenido=$actual"; fail=1; fi\n}\n\necho "Invariantes DB=$PGDATABASE tenant=${TENANT:-no especificado}"\nif [[ -n "$TENANT" ]]; then\n  if ! [[ "$TENANT" =~ ^[0-9a-fA-F-]{36}$ ]]; then echo "Tenant UUID inválido"; exit 2; fi\n  check_zero "audit_chain_broken tenant" "SELECT count(*) FROM public.verify_audit_chain('$TENANT')"\nfi\ncheck_zero "outbox dead-letter" "SELECT count(*) FROM public.projection_outbox WHERE status='DEAD_LETTERED'"\ncheck_zero "recovery_account saldo negativo" "SELECT count(*) FROM public.recovery_account WHERE saldo_pendiente < 0"\ncheck_zero "progress certificado bajo threshold" "SELECT count(*) FROM public.progress_observation WHERE status='CERTIFIED' AND progress_ratio_lower < contractual_threshold"\ncheck_zero "incidente no-recordable sin justificación" "SELECT count(*) FROM public.safety_incident WHERE osha_recordability='NOT_RECORDABLE_WITH_JUSTIFICATION' AND osha_justification IS NULL"\ncheck_zero "match incoherente" "SELECT count(*) FROM public.three_way_match_result WHERE estado='MATCH' AND jsonb_array_length(diferencias) > 0"\ncheck_zero "payment marcados EXECUTED sin executed_at" "SELECT count(*) FROM public.payment WHERE status='EXECUTED' AND executed_at IS NULL"\n\nif (( fail )); then echo "RESULT: invariantes fallaron o una consulta no pudo ejecutarse."; exit 1; fi\necho "RESULT: invariantes consultados pasaron; no demuestra aislamiento RLS ni comportamiento no cubierto."